def steps(u):
    H=HOMES[u]; back='gen.home.back.'+u.replace('.','')
    home={"s":"hook","scene":"homeNums","unit":u,"art":H['art'],"ask":H['ask'][0],"fields":H['fields'],"lines":[back]}
    if H.get('say'): home['say']=H['say']
    again={"s":"hook","scene":"homeNums","unit":u,"art":H['art'],"again":H['again_fields'],"askAgain":H['askAgain'][0],"sayAgain":H['sayAgain'],"quiet":True,"lines":[]}
    return home, again
def inject(obj):
    if not isinstance(obj, dict) or 'flow' not in obj: return
    for u,H in HOMES.items():
        home, again = steps(u)
        has = lambda: any(isinstance(st, dict) and st.get('scene') == 'homeNums' and st.get('unit') == u for st in obj['flow'])
        if obj.get('id') == H['at'] and not has(): obj['flow'].insert(0, home)
        if obj.get('id') in H['again'] and not has(): obj['flow'].insert(0, again)
if __name__ == '__main__':
    import json, os
    ROOT = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..')
    p = ROOT + '/content/strings/gen.json'; g = json.load(open(p, encoding='utf8')); n = 0
    for u,H in HOMES.items():
        for k,v in [H['ask'], H['askAgain']] + list(H['lines'].items()): g['lines'][k] = v; n += 1
        g['lines']['gen.home.back.'+u.replace('.','')] = H['back']; n += 1
    open(p, 'w', encoding='utf8').write(json.dumps(g, ensure_ascii=False, indent=1) + '\n')
    p = ROOT + '/content/strings/labels.json'; raw = open(p, encoding='utf8').read(); l = json.loads(raw)
    for k,v in LABELS.items(): l['ui'][k] = v
    open(p, 'w', encoding='utf8').write(json.dumps(l, ensure_ascii=False, indent=1) + ('\n' if raw.endswith('\n') else '')); print('ok', n, 'جملة بيت')
